test("connection failure -> JEV_UNAVAILABLE", async () => {
    const broken: FetchLike = async () => {
      throw new TypeError("fetch failed");
    };
    try {
      await judgeOnce(broken);
      expect.unreachable();
    } catch (e) {
      expectMeasureError("JEV_UNAVAILABLE")(e);
    }
  });
